# JAX wrapper
def log_likelihood_jax(theta):
    return jax.pure_callback(
        lambda t: compute_log_lik(t.ctypes.data_as(...), len(t)),
        jax.ShapeDtypeStruct((), jnp.float64),
        theta
    )

# Use with SVGD
